1	// @vitest-environment node
2	/**
3	 * Rendered-layout regression for the UX-01 compact row (real Chrome, real CSS).
4	 *
5	 * This is the P1 guard for the compact conversation row at the 1000 CSS px
6	 * supported desktop breakpoint: with an unknown read state (and, in the worst
7	 * case, a pending membership operation) the row metadata was unbounded and
8	 * collapsed the subject/snippet column to zero width. jsdom has no layout, so
9	 * these assertions only mean something against real rendered CSS.
10	 *
11	 * The second P1 guard covers larger user text: at 1000px with the long old
12	 * date label, a 24px root font still fits inline (the sender column gives up
13	 * width first); from about 26px the full inline metadata no longer fits, so
14	 * the adaptive compact presentation collapses the actions behind a named,
15	 * keyboard- and pointer-operable disclosure (still without overflow at 28px
16	 * and 30px) instead of trading subject collapse for horizontal overflow.
17	 *
18	 * Opt-in only: set EMAIL_OS_RENDERED_LAYOUT_CHROME to a Chrome/Chromium binary
19	 * path to run, e.g.
20	 *
21	 *   EMAIL_OS_RENDERED_LAYOUT_CHROME=/path/to/chrome \
22	 *     mise run test:rendered
23	 *
24	 * The test starts its own ephemeral Vite dev server and its own headless
25	 * Chrome profile (synthetic in-memory browser fake only — never real Gmail,
26	 * never real mail), and tears both down in `afterAll`. Default `pnpm test`
27	 * the default test task excludes it.
28	 */
29	import { afterAll, beforeAll, describe, expect, it } from 'vitest';
30	import { startRenderedHarness, type RenderedHarness } from '../rendered/chromium';
31	
32	const chromePath = process.env.EMAIL_OS_RENDERED_LAYOUT_CHROME ?? '';
