67	  /** Replaces the default shell with a fresh synthetic browser-fake app. */
68	  const MOUNT_SCRIPT = `(async () => {
69	  const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
70	  if (!vueUrl) throw new Error('Vite Vue dep not found');
71	  const { createApp } = await import(vueUrl);
72	  const { default: App } = await import('/src/App.vue');
73	  const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
74	  window.__layoutMount = async (mode, options = {}) => {
75	    const root = document.querySelector('#app');
76	    root.__vue_app__?.unmount();
77	    const fake = createBrowserFakeMailClient();
78	    if (mode === 'gmail-actions') {
79	      fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
80	    }
81	    window.__layoutFake = fake;
82	    // The long old-date label is the widest realistic trailing date.
83	    const client = options.oldDate
84	      ? { ...fake, listConversations: async () => {
85	          const snapshot = await fake.listConversations();
86	          return { ...snapshot, conversations: snapshot.conversations.map((r) => r.ref.conversationId === 'conv-01' || r.ref.conversationId === 'conv-17' ? { ...r, lastMessageAt: '2001-09-30T09:00:00Z' } : r) };
87	        } }
88	      : fake;
89	    createApp(App, { client, mode: 'browser-preview' }).mount(root);
90	  };
