93	  const MEASURE_SCRIPT = `(() => {
94	  const row = document.querySelector('[data-test="conversation-row-conv-01"]');
95	  if (!row) throw new Error('conv-01 row missing');
96	  const rect = (el) => { const r = el.getBoundingClientRect(); return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height }; };
97	  const subject = row.querySelector('.row-subject');
98	  const textNode = subject.firstChild;
99	  const box = subject.getBoundingClientRect();
100	  // Range client rects are clipped by text-overflow: ellipsis, so they cannot
101	  // count hidden characters. caretRangeFromPoint walks the actually-rendered
102	  // prefix: the deepest text offset reachable inside the subject box is the
103	  // number of leading characters a reader can see.
104	  const midY = box.top + box.height / 2;
105	  let visibleChars = 0;
106	  for (const frac of [0.55, 0.7, 0.85, 0.95]) {
107	    const caret = document.caretRangeFromPoint(box.left + box.width * frac, midY);
108	    if (caret && caret.startContainer === textNode) visibleChars = Math.max(visibleChars, caret.startOffset);
109	  }
110	  const pick = (selector) => { const el = row.querySelector(selector); return el ? { width: el.getBoundingClientRect().width, text: el.textContent, test: el.getAttribute('data-test'), label: el.getAttribute('aria-label') } : null; };
111	  const isVisible = (el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
112	  const focusedButtons = [];
113	  for (const button of row.querySelectorAll('button')) {
114	    button.focus();
115	    if (document.activeElement === button) focusedButtons.push(button.getAttribute('data-test'));
116	  }
117	  const toggle = row.querySelector('[data-test^="row-actions-toggle-"]');
118	  const panel = row.querySelector('.row-actions');
119	  const panelStyle = panel ? getComputedStyle(panel) : null;
120	  return {
121	    innerWidth,
122	    clientMode: document.querySelector('.app')?.getAttribute('data-client-mode') ?? null,
123	    row: rect(row),
124	    rowScrollWidth: row.scrollWidth,
125	    rowClientWidth: row.clientWidth,
126	    listScrollWidth: document.querySelector('.inbox-scroll').scrollWidth,
127	    listClientWidth: document.querySelector('.inbox-scroll').clientWidth,
128	    sender: rect(row.querySelector('.row-sender')),
129	    subjectSnippet: rect(row.querySelector('.row-subject-snippet')),
130	    subject: { left: box.left, right: box.right, width: box.width, visibleChars, truncated: subject.scrollWidth > subject.clientWidth + 0.5, text: subject.textContent },
131	    meta: rect(row.querySelector('.row-meta')),
132	    date: row.querySelector('.row-time')?.textContent ?? null,
133	    pending: pick('[data-test="row-pending"]'),
134	    readState: pick('[data-test="row-read-unknown"], [data-test="row-read"], [data-test="row-unread"]'),
135	    buttons: [...row.querySelectorAll('button')].map((b) => ({ name: (b.getAttribute('aria-label') ?? b.textContent ?? '').trim(), test: b.getAttribute('data-test'), visible: isVisible(b), ...rect(b) })),
136	    focusedButtons,
137	    toggle: toggle ? { visible: isVisible(toggle), ariaExpanded: toggle.getAttribute('aria-expanded'), ...rect(toggle) } : null,
138	    actionsPanel: panel && panelStyle ? { position: panelStyle.position, visibility: panelStyle.visibility, width: panel.getBoundingClientRect().width } : null,
139	  };
140	})()`;
