169	  /** Real CDP key event (trusted input), not HTMLElement dispatch. */
170	  async function realKey(key: 'Tab' | 'Enter' | 'Escape'): Promise<void> {
171	    const virtualKey = key === 'Tab' ? 9 : key === 'Enter' ? 13 : 27;
172	    // Enter needs the carriage-return text payload for Chrome to run the
173	    // native button-activation default action on the trusted keydown.
174	    await cdp!.cmd('Input.dispatchKeyEvent', { type: 'keyDown', key, code: key, windowsVirtualKeyCode: virtualKey, ...(key === 'Enter' ? { text: '\r' } : {}) });
175	    await cdp!.cmd('Input.dispatchKeyEvent', { type: 'keyUp', key, code: key, windowsVirtualKeyCode: virtualKey });
176	    await tick();
177	  }
