179	  /** Real CDP mouse click at the center of a measured rect (trusted input). */
180	  async function realClick(r: Rect): Promise<void> {
181	    const x = r.left + r.width / 2;
182	    const y = r.top + r.height / 2;
183	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
184	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', buttons: 1, clickCount: 1 });
185	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', buttons: 0, clickCount: 1 });
186	    await tick();
187	  }
