189	  function assertCompactRowLayout(m: RowMeasure, options: { minVisibleChars: number; expectPending: boolean; expectFullSubject?: boolean; expectCompact?: boolean }): void {
190	    // Synthetic-only guard: these numbers are meaningless outside the labelled preview.
191	    expect(m.clientMode).toBe('browser-preview');
192	    expect(m.innerWidth).toBeGreaterThanOrEqual(1000);
193	
194	    // The subject/snippet column never collapses; the subject itself keeps a
195	    // readable prefix of the fixture text visible ("Fixture thread …").
196	    expect(m.subjectSnippet.width).toBeGreaterThanOrEqual(120);
197	    expect(m.subject.width).toBeGreaterThanOrEqual(100);
198	    expect(m.subject.visibleChars).toBeGreaterThanOrEqual(options.minVisibleChars);
199	    expect(m.subject.text).toBe('Fixture thread 1: weekly status');
200	    if (options.expectFullSubject) {
201	      // Wide desktop sanity: the whole subject renders without truncation.
202	      expect(m.subject.truncated).toBe(false);
203	    }
204	
205	    // Single-line scanning rhythm, no horizontal overflow anywhere in the row.
206	    expect(m.row.height).toBeLessThanOrEqual(48);
207	    expect(m.rowScrollWidth).toBeLessThanOrEqual(m.rowClientWidth + 1);
208	    expect(m.listScrollWidth).toBeLessThanOrEqual(m.listClientWidth + 1);
209	
210	    const visibleButtons = m.buttons.filter((b) => b.visible);
211	    if (options.expectCompact) {
212	      // Adaptive compact presentation: the inline actions leave the flow behind
213	      // the named disclosure control — hidden, never clipped, still measurable.
214	      expect(m.toggle).not.toBeNull();
215	      expect(m.toggle!.visible).toBe(true);
216	      expect(m.toggle!.ariaExpanded).toBe('false');
217	      // The disclosure toggle is the only visible row action control.
218	      expect(visibleButtons.map((b) => b.test)).toEqual(['row-actions-toggle-conv-01']);
219	      expect(m.actionsPanel!.position).toBe('absolute');
220	      expect(m.actionsPanel!.visibility).toBe('hidden');
221	      expect(m.actionsPanel!.width).toBeGreaterThan(0);
222	    } else {
223	      // Expanded presentation: every action stays a visible, named,
224	      // keyboard-reachable control inside the row.
225	      expect(visibleButtons.length).toBeGreaterThan(0);
226	      for (const button of visibleButtons) {
227	        expect(button.width).toBeGreaterThan(0);
228	        expect(button.right).toBeLessThanOrEqual(m.row.right + 0.5);
229	        expect(button.name.length).toBeGreaterThan(0);
230	      }
231	      expect(m.actionsPanel!.visibility).toBe('visible');
232	      expect(m.focusedButtons).toHaveLength(visibleButtons.length);
233	    }
234	
235	    // Pending and read-state disclosures stay visible (not clipped away).
236	    if (options.expectPending) {
237	      expect(m.pending).not.toBeNull();
238	      expect(m.pending!.width).toBeGreaterThan(0);
239	      expect(m.pending!.text).toBe('Pending…');
240	    }
241	    // The unknown read state is a visible gutter glyph with an exact name.
242	    expect(m.readState).not.toBeNull();
243	    expect(m.readState!.width).toBeGreaterThan(0);
244	    expect(m.readState!.test).toBe('row-read-unknown');
245	    expect(m.readState!.label).toBe('Read state unknown');
246	  }
